  // Helper method to validate if a key exists
  static String translate(BuildContext context, String key) {
    var instance = AppTranslations.of(context);
    String langCode = 'en'; // default

    if (instance != null) {
      langCode = instance.locale.languageCode;
    } else {
      langCode = LanguageService().currentLocale.value;
    }

    if (_translations.containsKey(langCode) &&
        _translations[langCode]!.containsKey(key)) {
      return _translations[langCode]![key]!;
    }

    // Check if the key exists in our separate profile translations map
    final extTrans = profileTranslations[langCode];
    if (extTrans != null && extTrans.containsKey(key)) {
      return extTrans[key]!;
    }

    // Fallback to English if the translation is not found in the current language
    if (_translations.containsKey('en') &&
        _translations['en']!.containsKey(key)) {
      return _translations['en']![key]!;
    }
    // Check profile translations english fallback
    final extTransEn = profileTranslations['en'];
    if (extTransEn != null && extTransEn.containsKey(key)) {
      return extTransEn[key]!;
    }

    if (_translations.containsKey('ar') &&
        _translations['ar']!.containsKey(key)) {
      return _translations['ar']![key]!;
    }
    return key; // return key if not found
  }

  static String translateWithoutContext(String languageCode, String key) {
    if (_translations.containsKey(languageCode) &&
        _translations[languageCode]!.containsKey(key)) {
      return _translations[languageCode]![key]!;
    }

    final extTrans = profileTranslations[languageCode];
    if (extTrans != null && extTrans.containsKey(key)) {
      return extTrans[key]!;
    }

    // Fallback to English if the translation is not found in the current language
    if (_translations.containsKey('en') &&
        _translations['en']!.containsKey(key)) {
      return _translations['en']![key]!;
    }

    final extTransEn = profileTranslations['en'];
    if (extTransEn != null && extTransEn.containsKey(key)) {
      return extTransEn[key]!;
    }

    if (_translations.containsKey('ar') &&
        _translations['ar']!.containsKey(key)) {
      return _translations['ar']![key]!;
    }
    return key; // return key if not found
  }
}

class AppTranslationsDelegate extends LocalizationsDelegate<AppTranslations> {
  const AppTranslationsDelegate();

  @override
  bool isSupported(Locale locale) {
    return [
      'en',
      'ar',
      'fr',
      'es',
      'de',
      'it',
      'pt',
      'nl',
      'ru',
      'pl',
      'sv',
      'el',
      'uk',
      'ro',
      'cs',
      'hu',
    ].contains(locale.languageCode);
  }

  @override
  Future<AppTranslations> load(Locale locale) async {
    return AppTranslations(locale);
  }

  @override
  bool shouldReload(AppTranslationsDelegate old) => false;
}

extension AppTranslationExtension on String {
  String tr(BuildContext context) {
    return AppTranslations.translate(context, this);
  }
}
